import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  DrawConfig,
  DrawableInk,
  FillerConfig,
  Generator,
  Randomizer,
  RoughPen,
  createFiller,
  point,
  toPathElements,
  toSvgPaths,
  type Drawable,
  type RoughFillStyle,
} from "../src/index.js";

// Generated by packages/skribble_rough/tool/js_parity_fixtures.dart.
const fixture = JSON.parse(readFileSync(new URL("./fixtures/dart-parity.json", import.meta.url), "utf8")) as {
  randoms: { seed: number; values: number[] }[];
  sample: { elements: string };
  cases: {
    shape: string;
    fillStyle: string;
    seed: number;
    roughness: number;
    pen?: "uniform" | "fineliner" | "ink" | "brush";
    svg: { outline: string; sketch: string; solid: string; elements: string };
    ink: string[];
  }[];
};

const P = point;
const shapes: Record<string, (g: Generator) => Drawable> = {
  rectangle: (g) => g.rectangle(4, 4, 192, 92),
  smallRectangle: (g) => g.rectangle(2, 3, 30, 20),
  ellipse: (g) => g.ellipse(100, 50, 180, 80),
  circle: (g) => g.circle(40, 40, 60),
  shortLine: (g) => g.line(10, 10, 40, 30),
  longLine: (g) => g.line(5, 5, 400, 120),
  veryLongLine: (g) => g.line(0, 0, 900, 40),
  polygon: (g) => g.polygon([P(10, 80), P(60, 5), P(120, 70), P(80, 110), P(30, 100)]),
  linearPath: (g) => g.linearPath([P(5, 5), P(80, 30), P(20, 70)]),
  arc: (g) => g.arc(100, 100, 160, 120, 0.3, Math.PI * 1.4),
  closedArc: (g) => g.arc(100, 100, 160, 120, -0.5, Math.PI, true),
  curve: (g) => g.curvePath([P(4, 50), P(40, 10), P(80, 40), P(116, 12)]),
  threePointCurve: (g) => g.curvePath([P(4, 50), P(40, 10), P(80, 40)]),
  roundedRectangle: (g) => g.roundedRectangle(4, 4, 220, 64, 16, 16, 16, 16),
  mixedRoundedRectangle: (g) => g.roundedRectangle(2, 2, 90, 40, 4, 12, 0, 30),
};

const dartFillStyles: Record<string, RoughFillStyle> = {
  none: "none",
  hachure: "hachure",
  crossHatch: "cross-hatch",
  zigzag: "zigzag",
  dashed: "dashed",
  dots: "dots",
  solid: "solid",
};

/** FNV-1a over UTF-16 code units, with the length, as the Dart tool writes it. */
function digest(value: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    hash = Math.imul(hash ^ value.charCodeAt(i), 0x01000193) >>> 0;
  }
  return `${hash.toString(16).padStart(8, "0")}:${value.length}`;
}

describe("parity with the Dart engine", () => {
  it("replays Dart's Random(seed).nextDouble() stream", () => {
    for (const { seed, values } of fixture.randoms) {
      const random = new Randomizer(seed);
      expect(values.map(() => random.next())).toEqual(values);
    }
  });

  it("covers every shape in the fixture", () => {
    expect(new Set(fixture.cases.map((c) => c.shape))).toEqual(new Set(Object.keys(shapes)));
  });

  it("renders the sample rectangle byte for byte", () => {
    const config = () => DrawConfig.build({ seed: 7, roughness: 1.2 });
    const generator = new Generator(
      config(),
      createFiller("hachure", FillerConfig.build({ drawConfig: config(), hachureGap: 8 })),
    );
    const svg = toSvgPaths(generator.rectangle(4, 4, 192, 92));
    expect(toPathElements(svg, { stroke: "#222", fill: "rgb(1, 2, 3)" })).toBe(fixture.sample.elements);
  });

  for (const c of fixture.cases) {
    const name = `${c.shape} · ${c.fillStyle} · seed ${c.seed} · roughness ${c.roughness}${c.pen ? ` · ${c.pen} pen` : ""}`;
    it(`draws ${name} like Dart`, () => {
      const pen = RoughPen[c.pen ?? "ink"];
      const config = () => DrawConfig.build({ seed: c.seed, roughness: c.roughness, pen });
      const style = dartFillStyles[c.fillStyle] as RoughFillStyle;
      const generator = new Generator(
        config(),
        createFiller(style, FillerConfig.build({ drawConfig: config(), hachureGap: 8 })),
      );
      const drawable = (shapes[c.shape] as (g: Generator) => Drawable)(generator);
      const svg = toSvgPaths(drawable);

      expect(digest(svg.outline)).toBe(c.svg.outline);
      expect(digest(svg.sketch)).toBe(c.svg.sketch);
      expect(digest(svg.solid)).toBe(c.svg.solid);
      expect(digest(toPathElements(svg, { stroke: "#222", fill: "rgb(1, 2, 3)" }))).toBe(c.svg.elements);

      const ink = new DrawableInk(drawable, { outlineWidth: 2, sketchWidth: 1 })
        .svgPaths()
        .filter((path) => path.filled && path.type !== "fillPath")
        .map((path) => digest(`${path.type} ${path.data}`));
      expect(ink).toEqual(c.ink);
    });
  }
});
